<script setup>
import{Link,usePage}from'@inertiajs/vue3';import{computed,ref}from'vue';
const props=defineProps({section:String}),page=usePage(),open=ref(false),items=computed(()=>page.props.settingsNavigation||[]),normalized=computed(()=>({preferences:'account-preferences',branding:'business-branding'}[props.section]||props.section)),active=item=>item.key===normalized.value;
</script>
<template><div class="h-fit"><button type="button" class="btn-secondary mb-3 w-full justify-between lg:hidden" :aria-expanded="open" aria-controls="settings-navigation" @click="open=!open"><span>Settings navigation</span><span aria-hidden="true">{{open?'▴':'▾'}}</span></button><nav id="settings-navigation" :class="['lp-card h-fit p-2',open?'block':'hidden lg:block']" aria-label="Settings navigation"><Link v-for="item in items" :key="item.key" :href="item.href" :aria-current="active(item)?'page':undefined" :class="['flex items-center justify-between rounded-xl px-4 py-3 text-sm font-semibold',active(item)?'bg-indigo/10 text-indigo':'text-slate-600 hover:bg-slate-50']" @click="open=false"><span>{{item.label}}</span><span v-if="item.badge" class="rounded-full bg-indigo/10 px-2 py-0.5 text-xs">{{item.badge}}</span></Link></nav></div></template>
